static float lr[256];
static double run(unsigned frames){double energy=0;while(frames){unsigned n=frames>128?128:frames;md_render(lr,n);for(unsigned k=0;k<2*n;k++){assert(std::isfinite(lr[k])&&fabsf(lr[k])<1);energy+=lr[k]*lr[k];}frames-=n;}return energy;}
static void cmd(int c,int t,int v){assert(md_command(c,t,v));run(1);if(c==MD_SCENE&&md_pending_biome()>=0){assert(md_command(MD_SCENE_CONFIRM,0,1));run(1);}}
static md_patch blank(int model=MD_MELLOW){md_init();cmd(MD_SCENE,0,64);md_patch p=*md_state();for(auto &t:p.track){t.mute=1;t.send=0;}auto &t=p.track[0];t.mute=0;t.model=model;t.attack=0;t.decay=600;t.level=500;t.filter=1;t.cutoff=700;t.note=48;p.macro[3]=0;return p;}
