 p=blank();p.macro[3]=700;p.grain_noise=1000;assert(md_load(&p));cmd(MD_PLAY,0,1);assert(run(MD_RATE*4)>.05);cmd(MD_PANIC,0,0);assert(run(MD_RATE)==0);puts("PASS mixed grain air audible; panic remains silent");
 p=blank();p.sequence[0].enabled=1;p.sequence[0].length=32;p.track[0].speed=1;p.tempo=220;
 for(auto &s:p.sequence[0].steps)s={0,80,100,50};p.sequence[0].steps[31]={60,90,100,40};assert(md_load(&p));cmd(MD_PLAY,0,1);run(MD_RATE*3);assert(md_status()->events[0]==1&&md_status()->last_note[0]==60);cmd(MD_PLAY,0,0);puts("PASS step 32 plays independently of Euclidean hits and old 16-step motifs");
 p=blank();assert(md_load(&p));cmd(MD_RECORD,0,1);cmd(MD_TRIGGER,0,55);assert(md_state()->sequence[0].steps[0].note==55&&md_state()->sequence[0].edit==1);md_midi(0x91,60,100,0);assert(md_state()->sequence[0].edit==1&&!md_state()->sequence[1].enabled);md_midi(0x90,62,64,0);assert(md_state()->sequence[0].steps[1].note==62&&md_state()->sequence[0].steps[1].velocity==50);cmd(MD_RECORD,0,0);auto saved=*md_state();assert(md_import(&saved,sizeof saved));assert(!memcmp(md_state()->sequence,saved.sequence,sizeof saved.sequence));puts("PASS keyboard and MIDI step entry, track isolation, velocity, patch round trip");
